import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {sourcePrefixHash} from '../live-paper/native-journal-restore.mjs';import {sha} from '../live-paper/native-dip-proof-v1.mjs';import {atomicJson} from '../execution/ledger.mjs';
const r=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),read=f=>JSON.parse(fs.readFileSync(f)),mode=process.argv[2];assert(['before','after'].includes(mode));const file='data/native-intent-preservation-20261004.json',prior=mode==='after'?read(file):null,banks={};
for(const type of ['baal-pair','no-maker','probability-receipt']){const activeFile=path.join(r,type+'-active.json'),active=read(activeFile),dir=path.join(r,type+'-cohorts',active.cohort),journal=path.join(dir,'journal.jsonl'),bytes=fs.statSync(journal).size,x={cohort:active.cohort,activeHash:sha(fs.readFileSync(activeFile)),bankHash:sha(fs.readFileSync(path.join(dir,'bank.json'))),journalBytes:bytes,journalPrefixHash:await sourcePrefixHash(journal,bytes)};if(prior){const old=prior.banks[type];assert.equal(x.activeHash,old.activeHash);assert.equal(x.bankHash,old.bankHash);assert(bytes>=old.journalBytes);assert.equal(await sourcePrefixHash(journal,old.journalBytes),old.journalPrefixHash);}banks[type]=x;}
const cacheActive=read(path.join(r,'native-dip-cache-active.json')),cacheActiveHash=sha(fs.readFileSync(path.join(r,'native-dip-cache-active.json'))),cacheBindingHash=sha(fs.readFileSync(path.join(r,'native-capture-caches',cacheActive.cacheDirectory,'binding.json')));if(prior){assert.equal(cacheActiveHash,prior.cacheActiveHash);assert.equal(cacheBindingHash,prior.cacheBindingHash);}const intentActiveHash=sha(fs.readFileSync(path.join(r,'native-dip-intent-active.json')));if(prior)assert.equal(intentActiveHash,prior.intentActiveHash);const cohort='baal-dip-request-clock-20261004-v2',d=path.join(r,'research-cohorts',cohort,'declaration.json'),oldActiveHash=sha(fs.readFileSync(path.join(r,'native-dip-active.json'))),oldBindingHash=sha(fs.readFileSync(path.join(r,'research-cohorts',cohort,'native-clock-binding.json'))),declarationHash=sha(fs.readFileSync(d));if(prior){assert.equal(oldActiveHash,prior.oldActiveHash);assert.equal(oldBindingHash,prior.oldBindingHash);assert.equal(declarationHash,prior.declarationHash);}
atomicJson(mode==='before'?file:'data/native-intent-preservation-after-20261004.json',{schemaVersion:1,at:new Date().toISOString(),mode,banks,intentActiveHash,cacheActiveHash,cacheBindingHash,oldActiveHash,oldBindingHash,declarationHash,frozenBanksPreserved:true,originalJournalsPreserved:true,competitionOrders:0});console.log(JSON.stringify({mode,banks:Object.keys(banks),preserved:true}));
